INSERT INTO categories (id, name_uz, name_ru, code, sort_order, show_on_home, parent_id, created_at, updated_at)
SELECT gen_random_uuid()::text, 'Oshxona uchun', 'Для кухни', 'Kuhnya_uchun', 1, false, id, NOW(), NOW()
FROM categories WHERE code = 'Bytovaya_tekhnika' LIMIT 1;

